package com.sene.conect;

import android.Manifest;
import android.app.Activity;
import android.bluetooth.*;
import android.bluetooth.le.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.view.Gravity;
import android.widget.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class MainActivity extends Activity {
 private static final UUID SERVICE=UUID.fromString("6e400001-b5a3-f393-e0a9-e50e24dcca9e"), RX=UUID.fromString("6e400002-b5a3-f393-e0a9-e50e24dcca9e"), TX=UUID.fromString("6e400003-b5a3-f393-e0a9-e50e24dcca9e"), CCCD=UUID.fromString("00002902-0000-1000-8000-00805f9b34fb");
 private static final int GREEN=Color.rgb(22,201,120), NAVY=Color.rgb(7,27,53), INK=Color.rgb(17,39,65), MUTED=Color.rgb(112,130,150);
 private BluetoothAdapter adapter; private BluetoothLeScanner scanner; private BluetoothGatt gatt; private BluetoothGattCharacteristic writeChar;
 private final Handler handler=new Handler(Looper.getMainLooper()); private final Map<String,BluetoothDevice> found=new LinkedHashMap<>(); private final ArrayList<String> routes=new ArrayList<>();
 private SharedPreferences prefs; private LinearLayout devices,routesBox; private TextView connection,message,count; private EditText input; private String font="NORMAL"; private boolean scanning=false;

 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(NAVY);getWindow().setNavigationBarColor(NAVY);prefs=getSharedPreferences("sene",MODE_PRIVATE);loadRoutes();BluetoothManager m=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);adapter=m==null?null:m.getAdapter();render();permissions();if(adapter==null)status("Este celular no tiene Bluetooth BLE.");else if(!adapter.isEnabled())status("Activa Bluetooth en el celular.");}
 private void permissions(){ArrayList<String> p=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){if(checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)!=0)p.add(Manifest.permission.BLUETOOTH_SCAN);if(checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=0)p.add(Manifest.permission.BLUETOOTH_CONNECT);}else if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=0)p.add(Manifest.permission.ACCESS_FINE_LOCATION);if(!p.isEmpty())requestPermissions(p.toArray(new String[0]),41);}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 private GradientDrawable shape(int color,int r){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(r));return d;}
 private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}
 private TextView txt(String s,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 private Button btn(String s,int bg,int fg){Button b=new Button(this);b.setText(s);b.setTextColor(fg);b.setTextSize(12);b.setTypeface(null,Typeface.BOLD);b.setAllCaps(false);b.setBackground(shape(bg,14));return b;}
 private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(15),dp(15),dp(15),dp(15));c.setBackground(shape(Color.WHITE,18));c.setElevation(dp(2));return c;}
 private void title(LinearLayout p,String a,String b){p.addView(txt(a,16,INK,true),lp(-1,-2,0,0,0,3));p.addView(txt(b,12,MUTED,false),lp(-1,-2,0,0,0,9));}
 private void render(){
  LinearLayout base=new LinearLayout(this);base.setOrientation(1);base.setBackgroundColor(Color.rgb(244,247,250));ScrollView scroll=new ScrollView(this);LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(18),dp(18),dp(18),dp(28));scroll.addView(page);base.addView(scroll);setContentView(base);
  LinearLayout hero=new LinearLayout(this);hero.setOrientation(1);hero.setPadding(dp(20),dp(20),dp(20),dp(20));hero.setBackground(shape(NAVY,22));hero.addView(txt("SENE.CONECT",25,Color.WHITE,true));TextView sub=txt("CONTROL DE RUTAS",12,Color.rgb(179,205,225),true);sub.setLetterSpacing(.12f);hero.addView(sub);connection=txt("●  SIN ENLACE",13,Color.WHITE,true);hero.addView(connection,lp(-1,-2,0,14,0,0));page.addView(hero,lp(-1,-2,0,0,0,18));
  title(page,"MIS DISPOSITIVOS","Conecta tu controlador SENE por Bluetooth");LinearLayout dc=card();Button scan=btn("＋  AGREGAR DISPOSITIVO",GREEN,Color.WHITE);scan.setOnClickListener(v->startScan());dc.addView(scan,lp(-1,dp(52),0,0,0,12));devices=new LinearLayout(this);devices.setOrientation(1);dc.addView(devices);page.addView(dc,lp(-1,-2,0,0,0,18));renderDevices();
  title(page,"MIS RUTAS","Administra las rutas que enviarás al letrero");LinearLayout rc=card();count=txt("",11,MUTED,true);rc.addView(count,lp(-1,-2,0,0,0,10));input=new EditText(this);input.setHint("Escribe rutas separadas por punto\nEj. CENTRO.MERCADO.NORTE");input.setTextColor(INK);input.setHintTextColor(MUTED);input.setGravity(Gravity.TOP|Gravity.START);input.setMinLines(2);input.setPadding(dp(14),dp(13),dp(14),dp(13));input.setBackground(shape(Color.rgb(246,249,251),14));rc.addView(input,lp(-1,-2,0,0,0,10));Button save=btn("GUARDAR RUTAS",NAVY,Color.WHITE);save.setOnClickListener(v->addRoutes());rc.addView(save,lp(-1,dp(48),0,0,0,14));routesBox=new LinearLayout(this);routesBox.setOrientation(1);rc.addView(routesBox);page.addView(rc,lp(-1,-2,0,0,0,18));renderRoutes();
  title(page,"PRESENTACIÓN","Estilo de letra para el letrero");LinearLayout fc=card();LinearLayout row=new LinearLayout(this);for(String f:new String[]{"NORMAL","ANCHA","COMPACTA"}){Button x=btn(f,NAVY,Color.WHITE);x.setTextSize(10);x.setOnClickListener(v->{font=f;status("Fuente seleccionada: "+f);});LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(0,dp(44),1);q.setMargins(dp(3),0,dp(3),0);row.addView(x,q);}fc.addView(row);page.addView(fc,lp(-1,-2,0,0,0,18));message=txt("Listo para enviar rutas.",12,MUTED,false);page.addView(message);
 }
 private void status(String s){if(message!=null)message.setText(s);if(connection!=null)connection.setText(gatt==null?"●  SIN ENLACE":"●  CONECTADO");}
 private void startScan(){if(adapter==null)return;permissions();if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)!=0){status("Permiso Bluetooth requerido.");return;}if(!adapter.isEnabled()){status("Activa Bluetooth en el celular.");return;}if(gatt!=null){gatt.disconnect();gatt.close();gatt=null;writeChar=null;}found.clear();renderDevices();scanner=adapter.getBluetoothLeScanner();if(scanner==null){status("No se pudo iniciar Bluetooth BLE.");return;}try{scanner.startScan(callback);scanning=true;status("Buscando dispositivos SENE...");handler.postDelayed(this::stopScan,12000);}catch(SecurityException e){status("Permiso Bluetooth requerido.");}}
 private final ScanCallback callback=new ScanCallback(){@Override public void onScanResult(int t,ScanResult r){BluetoothDevice d=r.getDevice();String n=d.getName();if(n==null)n="";if(n.toUpperCase(Locale.ROOT).contains("SENE")){found.put(d.getAddress(),d);runOnUiThread(MainActivity.this::renderDevices);}}@Override public void onScanFailed(int e){runOnUiThread(()->status("No se encontraron dispositivos BLE."));}};
 private void stopScan(){if(scanner!=null&&scanning){try{scanner.stopScan(callback);}catch(SecurityException ignored){}scanning=false;}if(found.isEmpty())status("No se encontraron dispositivos BLE.");else status("Selecciona SENE cuando aparezca en la lista.");}
 private void renderDevices(){if(devices==null)return;devices.removeAllViews();if(found.isEmpty()){devices.addView(txt("Toca Agregar para buscar dispositivos.",13,MUTED,false));return;}for(BluetoothDevice d:found.values()){String n=d.getName();if(n==null)n="SENE";Button b=btn("◉  "+n+"   "+d.getAddress(),Color.rgb(237,245,241),INK);b.setOnClickListener(v->connect(d));devices.addView(b,lp(-1,dp(48),0,4,0,4));}}
 private void connect(BluetoothDevice d){stopScan();try{status("Enlazando con SENE...");if(Build.VERSION.SDK_INT>=31&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=0){status("Permiso Bluetooth requerido.");return;}gatt=d.connectGatt(this,false,gattCallback,BluetoothDevice.TRANSPORT_LE);}catch(SecurityException e){status("Permiso Bluetooth requerido.");}}
 private final BluetoothGattCallback gattCallback=new BluetoothGattCallback(){
  @Override public void onConnectionStateChange(BluetoothGatt g,int s,int state){runOnUiThread(()->{if(state==BluetoothProfile.STATE_CONNECTED){status("Buscando servicios SENE...");try{g.discoverServices();}catch(SecurityException ignored){}}else if(state==BluetoothProfile.STATE_DISCONNECTED){writeChar=null;status("Bluetooth desconectado.");}});}
  @Override public void onServicesDiscovered(BluetoothGatt g,int s){BluetoothGattService service=g.getService(SERVICE);if(service==null){runOnUiThread(()->status("Ese dispositivo no acepta rutas SENE."));return;}writeChar=service.getCharacteristic(RX);BluetoothGattCharacteristic notify=service.getCharacteristic(TX);if(notify!=null)try{g.setCharacteristicNotification(notify,true);BluetoothGattDescriptor d=notify.getDescriptor(CCCD);if(d!=null){d.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);g.writeDescriptor(d);}}catch(SecurityException ignored){}runOnUiThread(()->{status(writeChar==null?"Servicio SENE incompleto.":"Enlazado con SENE");prefs.edit().putString("device",g.getDevice().getAddress()).apply();});}
  @Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c){byte[] b=c.getValue();if(b!=null)runOnUiThread(()->status(new String(b,StandardCharsets.UTF_8).trim()));}
  @Override public void onCharacteristicWrite(BluetoothGatt g,BluetoothGattCharacteristic c,int s){runOnUiThread(()->status(s==0?"Rutas enviadas al controlador.":"No se pudo enviar."));}
 };
 private void addRoutes(){String raw=input.getText().toString().trim().toUpperCase(Locale.ROOT);if(raw.isEmpty()){status("Guarda al menos una ruta.");return;}for(String v:raw.split("[.\\n,;]+")){String r=v.trim().replaceAll("\\s+"," ");if(!r.isEmpty()&&!routes.contains(r)&&routes.size()<20)routes.add(r);}saveRoutes();input.setText("");renderRoutes();status("Rutas guardadas.");}
 private void renderRoutes(){if(routesBox==null)return;routesBox.removeAllViews();count.setText("RUTAS GUARDADAS  ·  "+routes.size()+" / 20");if(routes.isEmpty()){routesBox.addView(txt("No hay rutas guardadas.",13,MUTED,false));return;}for(int i=0;i<routes.size();i++){final int index=i;LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(dp(10),dp(9),dp(8),dp(9));r.setBackground(shape(Color.rgb(246,249,251),12));r.addView(txt(String.format(Locale.ROOT,"%02d   %s",i+1,routes.get(i)),14,INK,true),new LinearLayout.LayoutParams(0,-2,1));Button del=btn("×",Color.rgb(255,235,235),Color.rgb(190,55,55));del.setMinWidth(dp(42));del.setOnClickListener(v->{routes.remove(index);saveRoutes();renderRoutes();});r.addView(del);routesBox.addView(r,lp(-1,-2,0,3,0,3));}Button send=btn("ENVIAR RUTAS A SENE",GREEN,Color.WHITE);send.setOnClickListener(v->sendRoutes());routesBox.addView(send,lp(-1,dp(48),0,10,0,0));}
 private void loadRoutes(){String s=prefs.getString("routes","");if(!s.isEmpty())for(String r:s.split("\\n"))if(!r.trim().isEmpty()&&routes.size()<20)routes.add(r.trim());}
 private void saveRoutes(){prefs.edit().putString("routes",String.join("\n",routes)).apply();}
 private void sendRoutes(){if(gatt==null||writeChar==null){status("Primero enlaza con SENE.");return;}if(routes.isEmpty()){status("No hay rutas guardadas.");return;}long epoch=System.currentTimeMillis()/1000L;String msg="FUENTE="+font+";TIME="+epoch+";AMANDAR"+String.join(".",routes)+"\n";try{writeChar.setWriteType(BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT);writeChar.setValue(msg.getBytes(StandardCharsets.UTF_8));status(gatt.writeCharacteristic(writeChar)?"Enviando rutas...":"No se pudo enviar.");}catch(SecurityException e){status("Permiso Bluetooth requerido.");}}
 @Override protected void onDestroy(){stopScan();if(gatt!=null){try{gatt.close();}catch(Exception ignored){}gatt=null;}super.onDestroy();}
}
